                    elif any(w in kind for w in ('territory', 'base', 'zone', 'flag')):
                        territories.append(p)

    # Threat assessment
    nearest_enemy, enemy_dist = nearest(my_pos, enemies) if enemies else (None, None)
    nearest_resource, resource_dist = nearest(my_pos, resources) if resources else (None, None)
    nearest_territory, territory_dist = nearest(my_pos, territories) if territories else (None, None)

    # Determine mode heuristically
    mode = 'explore'
