        for dy in (-1, 0, 1):
            moves.append([dx, dy])

    best_move = [0, 0]
    best_score = None

    for dx, dy in moves:
        nx = my_pos[0] + dx
        ny = my_pos[1] + dy
        score = 0

        if mode == 'evade' and nearest_enemy is not None:
            score += abs(nx - nearest_enemy[0]) + abs(ny - nearest_enemy[1])

        if mode == 'collect' and nearest_resource is not None:
            score -= abs(nx - nearest_resource[0]) + abs(ny - nearest_resource[1])

        if mode == 'territory' and nearest_territory is not None:
            score -= abs(nx - nearest_territory[0]) + abs(ny - nearest_territory[1])

        # Prefer staying put less when no target
        if dx == 0 and dy == 0:
            score -= 0.25

        # Mild penalty for moving toward enemy even in other modes
        if nearest_enemy is not None:
            score -= 0.2 * (1 if abs(nx - nearest_enemy[0]) + abs(ny - nearest_enemy[1]) < (enemy_dist if enemy_dist is not None else 999) else 0)

        # Mild exploration bias toward map center if known
