            cx = (w - 1) / 2.0
            cy = (h - 1) / 2.0
            score -= 0.05 * (abs(nx - cx) + abs(ny - cy))

        if best_score is None or score > best_score:
            best_score = score
            best_move = [dx, dy]

    return [clamp(best_move[0]), clamp(best_move[1])]

